      state.index,
      byte,
    )];
  }

  static bool transitionReenters(VtParserState state, int byte) {
    _checkByte(byte);
    return transitionReentersUnchecked(state.index, byte);
  }

  static VtParserAction entryAction(VtParserState state) =>
      VtParserAction.values[entryActionIdUnchecked(state.index)];

  static VtParserAction exitAction(VtParserState state) =>
      VtParserAction.values[exitActionIdUnchecked(state.index)];

  static void _checkByte(int byte) {
    if (byte < 0 || byte >= byteCount) {
      throw RangeError.range(byte, 0, byteCount - 1, 'byte');
    }
  }
}
